"""Solver stress test with protocol valid instances (simple directed walks)."""
import random
import sys
import os

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
sys.path.insert(0, os.path.join(ROOT, 'submission'))
import numpy as np
from te.algorithms.formulations.path_based.distributed.worker import WorkerSolver


def tol(a, b):
    return 1e-7 + 1e-7 * max(abs(a), abs(b))


def random_instance(rng):
    nodes = rng.randint(2, 8)
    pairs = [(u, v) for u in range(nodes) for v in range(nodes) if u != v]
    rng.shuffle(pairs)
    edges = []
    index = {}
    for u, v in pairs[:rng.randint(1, min(12, len(pairs)))]:
        index[(u, v)] = len(edges)
        edges.append((u, v, rng.choice([0, 1, 1, 2, 5, 50, 1000])))
    out = {}
    for eid, (u, v, _c) in enumerate(edges):
        out.setdefault(u, []).append(eid)

    def walk(source, sink):
        path = []
        node = source
        visited = {source}
        for _ in range(rng.randint(1, 6)):
            if node == sink:
                break
            options = [e for e in out.get(node, []) if edges[e][1] not in visited]
            if not options:
                break
            choice = rng.choice(options)
            path.append(choice)
            node = edges[choice][1]
            visited.add(node)
        if node == sink and path:
            return path
        return None

    commodities = []
    for _ in range(rng.randint(1, 8)):
        source = rng.randrange(nodes)
        sink = rng.randrange(nodes)
        while sink == source:
            sink = rng.randrange(nodes)
        paths = []
        for _ in range(rng.randint(0, 6)):
            paths.append(walk(source, sink))
        seen = set()
        unique = []
        for path in paths:
            key = None if path is None else tuple(path)
            if key in seen:
                continue
            seen.add(key)
            unique.append(path)
        commodities.append({'source': source, 'sink': sink,
                            'demand': rng.choice([0, 1, 3, 17, 100, 1000]),
                            'paths': unique})
    capacities = [float(c) for _u, _v, c in edges]
    bias = [rng.choice([0.0, rng.uniform(-50, 50)]) for _ in edges]
    rho = rng.choice([1, 2, 3, 8])
    mode = rng.choice(['route', 'admit'])
    return capacities, [c['demand'] for c in commodities], [c['paths'] for c in commodities], bias, rho, mode


def verify(capacities, demands, paths, bias, rho, mode, result):
    problems = []
    num_edges = len(capacities)
    if result['status'] == 'infeasible':
        expected = sorted(k for k in range(len(demands))
                          if demands[k] > 0 and not any(
                              all(capacities[e] > 0 for e in path) for path in paths[k] if path))
        if result['unroutable'] != expected:
            problems.append('unroutable %r != %r' % (result['unroutable'], expected))
        return problems
    flow = result['flow']
    potential = result['potential']
    loads = result['edge_load']
    recomputed = [0.0] * num_edges
    for k in range(len(demands)):
        for p, amount in enumerate(flow[k]):
            path = paths[k][p]
            available = path is not None and all(capacities[e] > 0 for e in path)
            if not available and amount != 0.0:
                problems.append('unavailable slot carries traffic')
            if demands[k] == 0 and amount != 0.0:
                problems.append('zero demand carries traffic')
            if amount < 0:
                problems.append('negative amount')
            if available:
                for e in path:
                    recomputed[e] += amount
    for e in range(num_edges):
        if abs(loads[e] - recomputed[e]) > tol(loads[e], recomputed[e]):
            problems.append('load mismatch %r %r' % (loads[e], recomputed[e]))
    total = 0.0
    R = 0.0
    for k in range(len(demands)):
        used = sum(flow[k])
        if demands[k] == 0 and used != 0:
            problems.append('zero demand traffic')
        if mode == 'route' and abs(used - demands[k]) > tol(used, demands[k]):
            problems.append('route budget')
        if mode == 'admit' and used > demands[k] + tol(used, demands[k]):
            problems.append('admit budget')
        if mode == 'admit' and potential[k] < 0.0:
            problems.append('negative admit potential %r' % potential[k])
        if demands[k] == 0 and potential[k] != 0.0:
            problems.append('zero demand potential')
        for p, amount in enumerate(flow[k]):
            path = paths[k][p]
            if not path or demands[k] == 0:
                continue
            if not all(capacities[e] > 0 for e in path):
                continue
            R += amount
            g = amount
            for e in path:
                g += rho * (recomputed[e] / capacities[e] - bias[e]) / capacities[e]
            if mode == 'admit':
                g -= 1.0
            total += amount * g
            if g + potential[k] < -tol(g, potential[k]):
                problems.append('KKT violation %r' % (g + potential[k]))
    f = 0.5 * sum(a * a for k in range(len(demands)) for a in flow[k])
    for e in range(num_edges):
        if capacities[e] > 0:
            f += 0.5 * rho * (recomputed[e] / capacities[e] - bias[e]) ** 2
    if mode == 'admit':
        f -= R
    D = f - total - sum(demands[k] * potential[k] for k in range(len(demands)))
    if abs(f - D) > tol(f, D):
        problems.append('identity %r %r' % (f, D))
    return problems


def main():
    rng = random.Random(4242)
    failures = 0
    solved = 0
    for trial in range(20000):
        capacities, demands, paths, bias, rho, mode = random_instance(rng)
        solver = WorkerSolver(len(capacities))
        solver.configure(capacities, demands, paths, list(range(len(demands))), bias, rho, mode)
        result = solver.solve()
        problems = verify(capacities, demands, paths, bias, rho, mode, result)
        if result['status'] == 'optimal':
            solved += 1
        if problems:
            failures += 1
            if failures <= 5:
                print('trial', trial, mode, problems[:3])
    print('%d failures out of %d instances (%d optimal)' % (failures, 20000, solved))


if __name__ == '__main__':
    main()
